PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'consulta',active INTEGER NOT NULL DEFAULT 1,must_change_password INTEGER NOT NULL DEFAULT 1,failed_attempts INTEGER NOT NULL DEFAULT 0,locked_until TEXT,last_login_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,ip TEXT NOT NULL,succeeded INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_attempts ON login_attempts (ip,created_at);
CREATE INDEX IF NOT EXISTS idx_email_attempts ON login_attempts(email,created_at);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,module TEXT NOT NULL,record_id INTEGER,details TEXT,ip TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_audit_record ON audit_logs(module,record_id);
CREATE TABLE IF NOT EXISTS works(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,type TEXT,local TEXT,responsible TEXT,status TEXT DEFAULT 'Planejada',progress REAL NOT NULL DEFAULT 0,budget REAL NOT NULL DEFAULT 0,contract_ref TEXT,start_date TEXT,end_date TEXT,description TEXT,latitude REAL,longitude REAL,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,work_id INTEGER REFERENCES works(id) ON DELETE SET NULL,local TEXT,requester TEXT,responsible TEXT,priority TEXT,status TEXT DEFAULT 'Aberta',due_date TEXT,description TEXT,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,work_id INTEGER REFERENCES works(id) ON DELETE SET NULL,responsible TEXT,type TEXT,inspection_date TEXT,status TEXT DEFAULT 'Pendente',description TEXT,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,work_id INTEGER REFERENCES works(id) ON DELETE SET NULL,type TEXT,document_date TEXT,status TEXT DEFAULT 'Em elaboração',version TEXT DEFAULT '1',description TEXT,original_filename TEXT,stored_filename TEXT,mime_type TEXT,file_size INTEGER,uploaded_by INTEGER,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS measurements(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,work_id INTEGER REFERENCES works(id) ON DELETE SET NULL,period TEXT,value REAL NOT NULL DEFAULT 0,responsible TEXT,status TEXT DEFAULT 'Em análise',description TEXT,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS materials(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,unit TEXT,local TEXT,quantity REAL NOT NULL DEFAULT 0,minimum REAL NOT NULL DEFAULT 0,description TEXT,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,material_id INTEGER NOT NULL REFERENCES materials(id),movement_type TEXT NOT NULL,amount REAL NOT NULL,note TEXT,user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_movements_material ON stock_movements(material_id,created_at);
CREATE TABLE IF NOT EXISTS buildings(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,local TEXT,type TEXT,area REAL,responsible TEXT,condition_status TEXT,status TEXT DEFAULT 'Em uso',description TEXT,latitude REAL,longitude REAL,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS protocols(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,origin_department TEXT,destination_department TEXT,opened_on TEXT,priority TEXT DEFAULT 'Normal',status TEXT DEFAULT 'Em análise',description TEXT,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS protocol_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,protocol_id INTEGER NOT NULL REFERENCES protocols(id),from_department TEXT,to_department TEXT,note TEXT,user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_protocol_history ON protocol_movements(protocol_id,created_at);
CREATE TABLE IF NOT EXISTS milestones(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,title TEXT NOT NULL,work_id INTEGER REFERENCES works(id) ON DELETE SET NULL,due_date TEXT,status TEXT DEFAULT 'Programado',description TEXT,created_by INTEGER,updated_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
